      function suggestedValidRole() {
        if (state.aiRole === 'none') return 'prohibited';
        if (state.aiRole === 'collaborator') return 'required';
        if (state.aiRole === 'critique') return 'encouraged';
        return ['high', 'uncertain', 'moderate'].includes(state.risk) ? 'constrained' : 'permitted';
      }

