        root.querySelector('#valid-drawer-icon').innerHTML = icon({ sheet: 'file', rubric: 'table', more: 'layers', guide: 'help', framework: 'steps', references: 'book' }[which], 18);
        drawer.querySelectorAll('[data-drawer]').forEach(node => { node.hidden = node.dataset.drawer !== which; });
        exampleChoice = '';
